{
  "name": "bt_tx_power_switch",
  "confidence": "medium",
  "docstring": "Handles Bluetooth TX power switch commands by updating per-link switch/descriptor state, optionally reading connection info or clearing an IRQ, and then dispatching the command through the BT control layer.",
  "subsystem": "bt",
  "var_renames": {
    "a1": "link_index",
    "a2": "command",
    "v4": "bt_link_context_table"
  },
  "struct_hints": [
    {
      "offset": 1225,
      "meaning": "byte in the 1320-byte BT link context passed to BT read/dispatch, likely link state or connection handle"
    },
    {
      "offset": 4,
      "meaning": "volatile per-link switch/descriptor word, zeroed to disable and set from another table to enable"
    },
    {
      "offset": 20,
      "meaning": "per-link byte flag cleared after handling the command"
    }
  ]
}
